insert into public.posts_discover (id, author_id, content, image_url, location, city, likes_count, comments_count, created_at)
values
  (gen_random_uuid(), 'a0000001-0000-4000-8000-000000000001', 'Just wrapped an amazing networking event in Victoria Island. So many great connections made. If you''re in Lagos and into tech & business, let''s connect!', 'https://images.unsplash.com/photo-1515187029135-18ee286d815b?w=800&h=500&fit=crop', 'Victoria Island, Lagos', 'Lagos', 24, 5, '2025-01-29T10:00:00Z'),
  (gen_random_uuid(), 'a0000001-0000-4000-8000-000000000001', 'Excited to share that our new campaign is live. Grateful for the team and everyone who gave feedback along the way.', null, 'Lagos', 'Lagos', 12, 2, '2025-01-28T14:00:00Z'),
  (gen_random_uuid(), 'a0000002-0000-4000-8000-000000000002', 'Coffee and code at a new spot in Lekki. The vibe here is perfect for getting work done. Who else works remotely from Lagos?', null, 'Lekki Phase 1, Lagos', 'Lagos', 18, 3, '2025-01-29T08:30:00Z'),
  (gen_random_uuid(), 'a0000002-0000-4000-8000-000000000002', 'Shipped a small feature today. Sometimes the best progress is the one that just works.', null, 'Lagos', 'Lagos', 8, 1, '2025-01-27T16:00:00Z'),
  (gen_random_uuid(), 'a0000003-0000-4000-8000-000000000003', 'New collection drop happening this weekend at the pop-up in Ikeja. Would love to see some familiar faces!', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=500&fit=crop', 'Ikeja, Lagos', 'Lagos', 42, 12, '2025-01-28T16:00:00Z'),
  (gen_random_uuid(), 'a0000003-0000-4000-8000-000000000003', 'Mood board for the next season is finally done. So many ideas, so little time.', null, 'Lagos', 'Lagos', 19, 4, '2025-01-26T11:00:00Z'),
  (gen_random_uuid(), 'a0000004-0000-4000-8000-000000000004', 'Running a free workshop on business strategy next Saturday in Yaba. DM if you''d like to join — limited seats.', null, 'Yaba, Lagos', 'Lagos', 39, 15, '2025-01-27T14:00:00Z'),
  (gen_random_uuid(), 'a0000004-0000-4000-8000-000000000004', 'The best business relationships start with a simple conversation. Always happy to connect over coffee.', null, 'Lagos', 'Lagos', 22, 6, '2025-01-25T09:00:00Z'),
  (gen_random_uuid(), 'a0000005-0000-4000-8000-000000000005', 'Quick thought: the best networking happens when you focus on giving value first. Happy to share insights on finance and career growth.', null, 'Lagos', 'Lagos', 31, 8, '2025-01-28T12:00:00Z'),
  (gen_random_uuid(), 'a0000005-0000-4000-8000-000000000005', 'Market update: staying curious and connected. Reach out if you want to swap notes.', null, 'Lagos', 'Lagos', 14, 3, '2025-01-24T17:00:00Z'),
  (gen_random_uuid(), 'a0000006-0000-4000-8000-000000000006', 'User research day. Nothing beats watching someone use what you designed.', null, 'Lagos', 'Lagos', 27, 7, '2025-01-29T09:00:00Z'),
  (gen_random_uuid(), 'a0000006-0000-4000-8000-000000000006', 'Accessibility isn’t optional. Small changes can make a big difference.', null, 'Lagos', 'Lagos', 33, 9, '2025-01-27T10:00:00Z'),
  (gen_random_uuid(), 'a0000007-0000-4000-8000-000000000007', 'Entrepreneur life: some days you build, some days you fix. Today was a fix day.', null, 'Lagos', 'Lagos', 18, 4, '2025-01-28T13:00:00Z'),
  (gen_random_uuid(), 'a0000007-0000-4000-8000-000000000007', 'New project in the works. Can’t wait to share more soon.', null, 'Lagos', 'Lagos', 11, 2, '2025-01-26T15:00:00Z'),
  (gen_random_uuid(), 'a0000008-0000-4000-8000-000000000008', 'Sunset views from the mainland never get old. Grateful for this city and the creative community here.', 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?w=800&h=500&fit=crop', 'Mainland, Lagos', 'Lagos', 56, 7, '2025-01-28T18:00:00Z'),
  (gen_random_uuid(), 'a0000008-0000-4000-8000-000000000008', 'New track dropping soon. Music and stories are my language.', null, 'Lagos', 'Lagos', 41, 12, '2025-01-25T20:00:00Z'),
  (gen_random_uuid(), 'a0000009-0000-4000-8000-000000000009', 'Product folks in Lagos — what''s your biggest challenge right now? Building in public and would love to learn from you.', null, 'Lagos', 'Lagos', 22, 11, '2025-01-27T09:00:00Z'),
  (gen_random_uuid(), 'a0000009-0000-4000-8000-000000000009', 'Roadmap review done. Q1 is packed but exciting.', null, 'Lagos', 'Lagos', 9, 2, '2025-01-26T14:00:00Z'),
